					i.slugs.some((slug) => planSpecRefs.has(slug))
			);
		} else {
			result = [];
		}
	}

	return result;
}

/**
 * Paginate array
 */
function paginate<T>(
	items: T[],
	params?: { limit?: number; offset?: number }
): PaginatedResponse<T> {
	const limit = params?.limit ?? 50;
	const offset = params?.offset ?? 0;
	const paged = items.slice(offset, offset + limit);

	return {
		items: paged,
		total: items.length,
		offset,
		limit
	};
}

